BEGIN TRANSACTION;
CREATE TABLE "ai_providers" ("id" integer primary key autoincrement not null, "name" varchar not null, "display_name" varchar, "model_name" varchar, "daily_limit" integer not null default '1000', "is_active" tinyint(1) not null default '1', "priority" integer not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "ai_usage" ("id" integer primary key autoincrement not null, "provider" varchar not null, "user_id" integer, "tokens_used" integer not null default '0', "request_count" integer not null default '0', "date" date not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE "announcements" ("id" integer primary key autoincrement not null, "class_id" integer not null, "author_id" integer not null, "title" varchar not null, "body" text not null, "is_pinned" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("class_id") references "classes"("id") on delete cascade, foreign key("author_id") references "users"("id") on delete cascade);
CREATE TABLE "assignment_group_members" ("id" integer primary key autoincrement not null, "assignment_group_id" integer not null, "user_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("assignment_group_id") references "assignment_groups"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "assignment_groups" ("id" integer primary key autoincrement not null, "assignment_id" integer not null, "name" varchar not null, "created_by" integer not null, "is_full" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("assignment_id") references "assignments"("id") on delete cascade, foreign key("created_by") references "users"("id") on delete cascade);
CREATE TABLE "assignment_submissions" ("id" integer primary key autoincrement not null, "assignment_id" integer not null, "student_id" integer not null, "text_answer" text, "score" numeric, "feedback" text, "status" varchar check ("status" in ('submitted', 'graded', 'returned', 'late')) not null default 'submitted', "submitted_at" datetime not null default CURRENT_TIMESTAMP, "graded_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("assignment_id") references "assignments"("id") on delete cascade, foreign key("student_id") references "users"("id") on delete cascade);
CREATE TABLE "assignments" ("id" integer primary key autoincrement not null, "class_id" integer not null, "teacher_id" integer not null, "title" varchar not null, "description" text, "max_score" numeric not null default '100', "due_date" datetime, "allow_late" tinyint(1) not null default '0', "is_published" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, "type" varchar check ("type" in ('individual', 'group')) not null default 'individual', "max_group_size" integer not null default '4', "start_at" datetime, foreign key("class_id") references "classes"("id") on delete cascade, foreign key("teacher_id") references "users"("id") on delete cascade);
CREATE TABLE "audit_logs" ("id" integer primary key autoincrement not null, "user_id" integer, "action" varchar not null, "target_type" varchar, "target_id" integer, "details" text, "ip_address" varchar, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE "classes" ("id" integer primary key autoincrement not null, "school_id" integer, "grade_id" integer, "teacher_id" integer not null, "name" varchar not null, "subject" varchar, "description" text, "cover_photo" varchar, "color" varchar not null default '#7C3AED', "join_code" varchar not null, "invite_link" varchar, "is_active" tinyint(1) not null default '1', "max_students" integer not null default '200', "allow_student_chat" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("school_id") references "schools"("id") on delete cascade, foreign key("grade_id") references "grades"("id") on delete set null, foreign key("teacher_id") references "users"("id") on delete cascade);
CREATE TABLE "device_tokens" ("id" integer primary key autoincrement not null, "user_id" integer not null, "token" varchar not null, "platform" varchar check ("platform" in ('android', 'ios', 'web', 'desktop')) not null default 'android', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "enrollments" ("id" integer primary key autoincrement not null, "class_id" integer not null, "student_id" integer not null, "joined_at" datetime not null default CURRENT_TIMESTAMP, "is_class_leader" tinyint(1) not null default '0', "is_banned" tinyint(1) not null default '0', "progress_percent" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("class_id") references "classes"("id") on delete cascade, foreign key("student_id") references "users"("id") on delete cascade);
CREATE TABLE "files" ("id" integer primary key autoincrement not null, "uploader_id" integer not null, "related_type" varchar, "related_id" integer, "original_name" varchar not null, "stored_name" varchar not null, "file_path" varchar not null, "file_type" varchar, "file_size" integer, "is_public" tinyint(1) not null default '0', "download_count" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("uploader_id") references "users"("id") on delete cascade);
CREATE TABLE "grades" ("id" integer primary key autoincrement not null, "school_id" integer not null, "name" varchar not null, "order_index" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("school_id") references "schools"("id") on delete cascade);
CREATE TABLE "group_chat_members" ("id" integer primary key autoincrement not null, "group_id" integer not null, "user_id" integer not null, "role" varchar check ("role" in ('member', 'admin', 'owner')) not null default 'member', "joined_at" datetime not null default CURRENT_TIMESTAMP, "last_read_at" datetime, "is_muted" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("group_id") references "group_chats"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "group_chats" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "avatar" varchar, "type" varchar check ("type" in ('class', 'custom', 'private')) not null default 'custom', "class_id" integer, "created_by" integer not null, "invite_link" varchar, "join_code" varchar, "is_public" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("class_id") references "classes"("id") on delete cascade, foreign key("created_by") references "users"("id") on delete cascade);
CREATE TABLE "lesson_bookmarks" ("id" integer primary key autoincrement not null, "lesson_id" integer not null, "user_id" integer not null, "created_at" datetime not null default CURRENT_TIMESTAMP, foreign key("lesson_id") references "lessons"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "lesson_comments" ("id" integer primary key autoincrement not null, "lesson_id" integer not null, "user_id" integer not null, "parent_id" integer, "body" text not null, "created_at" datetime, "updated_at" datetime, foreign key("lesson_id") references "lessons"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade, foreign key("parent_id") references "lesson_comments"("id") on delete cascade);
CREATE TABLE "lesson_views" ("id" integer primary key autoincrement not null, "lesson_id" integer not null, "user_id" integer not null, "viewed_at" datetime not null default CURRENT_TIMESTAMP, foreign key("lesson_id") references "lessons"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "lessons" ("id" integer primary key autoincrement not null, "class_id" integer not null, "teacher_id" integer not null, "title" varchar not null, "description" text, "content" text, "order_index" integer not null default '0', "is_published" tinyint(1) not null default '1', "allow_comments" tinyint(1) not null default '1', "allow_downloads" tinyint(1) not null default '1', "views" integer not null default '0', "created_at" datetime, "updated_at" datetime, "chapter_name" varchar, foreign key("class_id") references "classes"("id") on delete cascade, foreign key("teacher_id") references "users"("id") on delete cascade);
CREATE TABLE "message_reads" ("id" integer primary key autoincrement not null, "message_id" integer not null, "user_id" integer not null, "read_at" datetime not null default CURRENT_TIMESTAMP, foreign key("message_id") references "messages"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "messages" ("id" integer primary key autoincrement not null, "sender_id" integer not null, "receiver_id" integer, "group_id" integer, "reply_to_id" integer, "forwarded_from_id" integer, "message_type" varchar check ("message_type" in ('text', 'image', 'video', 'audio', 'file', 'voice', 'system')) not null default 'text', "body" text, "is_edited" tinyint(1) not null default '0', "is_deleted" tinyint(1) not null default '0', "is_pinned" tinyint(1) not null default '0', "reactions" text, "metadata" text, "client_message_id" varchar, "created_at" datetime, "updated_at" datetime, foreign key("sender_id") references "users"("id") on delete cascade, foreign key("receiver_id") references "users"("id") on delete cascade, foreign key("group_id") references "group_chats"("id") on delete cascade, foreign key("reply_to_id") references "messages"("id") on delete set null, foreign key("forwarded_from_id") references "messages"("id") on delete set null);
CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE "notifications" ("id" integer primary key autoincrement not null, "user_id" integer not null, "type" varchar not null, "title" varchar not null, "body" text, "icon" varchar not null default 'bell', "related_type" varchar, "related_id" integer, "action_url" varchar, "is_read" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "personal_access_tokens" ("id" integer primary key autoincrement not null, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" varchar not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "quiz_attempts" ("id" integer primary key autoincrement not null, "quiz_id" integer not null, "student_id" integer not null, "answers" text not null, "score" numeric, "max_score" numeric, "percentage" numeric, "passed" tinyint(1), "needs_manual_grading" tinyint(1) not null default '0', "time_taken_seconds" integer, "started_at" datetime not null default CURRENT_TIMESTAMP, "submitted_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("quiz_id") references "quizzes"("id") on delete cascade, foreign key("student_id") references "users"("id") on delete cascade);
CREATE TABLE "quiz_questions" ("id" integer primary key autoincrement not null, "quiz_id" integer not null, "question_type" varchar not null default 'multiple_choice', "question_text" text not null, "options" text, "correct_answer" text, "points" numeric not null default '1', "order_index" integer not null default '0', "explanation" text, "created_at" datetime, "updated_at" datetime, foreign key("quiz_id") references "quizzes"("id") on delete cascade);
CREATE TABLE "quizzes" ("id" integer primary key autoincrement not null, "class_id" integer not null, "teacher_id" integer not null, "title" varchar not null, "description" text, "time_limit_minutes" integer, "max_attempts" integer not null default '1', "shuffle_questions" tinyint(1) not null default '0', "show_answers_after" tinyint(1) not null default '1', "pass_score" numeric not null default '50', "is_published" tinyint(1) not null default '0', "opens_at" datetime, "closes_at" datetime, "created_at" datetime, "updated_at" datetime, "max_score" integer not null default '100', foreign key("class_id") references "classes"("id") on delete cascade, foreign key("teacher_id") references "users"("id") on delete cascade);
CREATE TABLE "roles" ("id" integer primary key autoincrement not null, "name" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "schools" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "description" text, "logo" varchar, "cover_photo" varchar, "address" text, "city" varchar, "country" varchar not null default 'Ethiopia', "phone" varchar, "email" varchar, "website" varchar, "is_active" tinyint(1) not null default '1', "max_students" integer not null default '1000', "plan" varchar not null default 'free', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "student_progress" ("id" integer primary key autoincrement not null, "student_id" integer not null, "class_id" integer not null, "lessons_viewed" integer not null default '0', "lessons_total" integer not null default '0', "assignments_submitted" integer not null default '0', "assignments_total" integer not null default '0', "avg_quiz_score" numeric not null default '0', "quizzes_taken" integer not null default '0', "last_activity" datetime, "created_at" datetime, "updated_at" datetime, foreign key("student_id") references "users"("id") on delete cascade, foreign key("class_id") references "classes"("id") on delete cascade);
CREATE TABLE "study_room_members" ("id" integer primary key autoincrement not null, "study_room_id" integer not null, "user_id" integer not null, "role" varchar check ("role" in ('member', 'moderator')) not null default 'member', "created_at" datetime, "updated_at" datetime, foreign key("study_room_id") references "study_rooms"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "study_room_messages" ("id" integer primary key autoincrement not null, "study_room_id" integer not null, "user_id" integer not null, "body" text not null, "is_ai_response" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("study_room_id") references "study_rooms"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "study_rooms" ("id" integer primary key autoincrement not null, "creator_id" integer not null, "name" varchar not null, "subject" varchar, "description" text, "join_code" varchar not null, "is_public" tinyint(1) not null default '1', "is_active" tinyint(1) not null default '1', "linked_lesson_id" integer, "created_at" datetime, "updated_at" datetime, foreign key("creator_id") references "users"("id") on delete cascade, foreign key("linked_lesson_id") references "lessons"("id") on delete set null);
CREATE TABLE "user_settings" ("id" integer primary key autoincrement not null, "user_id" integer not null, "dark_mode" tinyint(1) not null default '0', "language" varchar not null default 'en', "notifications_enabled" tinyint(1) not null default '1', "email_notifications" tinyint(1) not null default '1', "sound_enabled" tinyint(1) not null default '1', "show_online_status" tinyint(1) not null default '1', "allow_messages_from" varchar check ("allow_messages_from" in ('everyone', 'classmates', 'nobody')) not null default 'everyone', "theme" varchar not null default 'purple', "font_size" varchar check ("font_size" in ('small', 'medium', 'large')) not null default 'medium', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "users" ("id" integer primary key autoincrement not null, "school_id" integer, "role_id" integer not null default '2', "first_name" varchar not null, "last_name" varchar not null, "username" varchar, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "google_id" varchar, "profile_photo" varchar, "cover_photo" varchar, "bio" text, "grade" varchar, "phone" varchar, "date_of_birth" date, "gender" varchar check ("gender" in ('male', 'female', 'other')), "is_active" tinyint(1) not null default '1', "is_online" tinyint(1) not null default '0', "last_seen" datetime, "remember_token" varchar, "otp_code_hash" varchar, "otp_expires_at" datetime, "otp_last_sent_at" datetime, "otp_attempts" integer not null default '0', "password_reset_token_hash" varchar, "password_reset_expires_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("school_id") references "schools"("id") on delete set null, foreign key("role_id") references "roles"("id"));
CREATE TABLE "video_meetings" ("id" integer primary key autoincrement not null, "class_id" integer, "host_id" integer not null, "title" varchar not null, "room_id" varchar not null, "scheduled_at" datetime, "started_at" datetime, "ended_at" datetime, "status" varchar check ("status" in ('scheduled', 'live', 'ended')) not null default 'scheduled', "is_recorded" tinyint(1) not null default '0', "recording_url" varchar, "participant_count" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("class_id") references "classes"("id") on delete set null, foreign key("host_id") references "users"("id") on delete cascade);
CREATE INDEX "personal_access_tokens_tokenable_type_tokenable_id_index" on "personal_access_tokens" ("tokenable_type", "tokenable_id");
CREATE UNIQUE INDEX "personal_access_tokens_token_unique" on "personal_access_tokens" ("token");
CREATE UNIQUE INDEX "roles_name_unique" on "roles" ("name");
CREATE UNIQUE INDEX "schools_slug_unique" on "schools" ("slug");
CREATE UNIQUE INDEX "users_username_unique" on "users" ("username");
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE UNIQUE INDEX "user_settings_user_id_unique" on "user_settings" ("user_id");
CREATE UNIQUE INDEX "classes_join_code_unique" on "classes" ("join_code");
CREATE UNIQUE INDEX "classes_invite_link_unique" on "classes" ("invite_link");
CREATE UNIQUE INDEX "enrollments_class_id_student_id_unique" on "enrollments" ("class_id", "student_id");
CREATE INDEX "files_related_type_related_id_index" on "files" ("related_type", "related_id");
CREATE UNIQUE INDEX "lesson_bookmarks_lesson_id_user_id_unique" on "lesson_bookmarks" ("lesson_id", "user_id");
CREATE UNIQUE INDEX "assignment_submissions_assignment_id_student_id_unique" on "assignment_submissions" ("assignment_id", "student_id");
CREATE UNIQUE INDEX "group_chats_invite_link_unique" on "group_chats" ("invite_link");
CREATE UNIQUE INDEX "group_chats_join_code_unique" on "group_chats" ("join_code");
CREATE UNIQUE INDEX "group_chat_members_group_id_user_id_unique" on "group_chat_members" ("group_id", "user_id");
CREATE INDEX "messages_sender_id_receiver_id_index" on "messages" ("sender_id", "receiver_id");
CREATE INDEX "messages_group_id_index" on "messages" ("group_id");
CREATE INDEX "messages_created_at_index" on "messages" ("created_at");
CREATE UNIQUE INDEX "messages_client_message_id_unique" on "messages" ("client_message_id");
CREATE UNIQUE INDEX "message_reads_message_id_user_id_unique" on "message_reads" ("message_id", "user_id");
CREATE INDEX "notifications_user_id_is_read_index" on "notifications" ("user_id", "is_read");
CREATE UNIQUE INDEX "lesson_views_lesson_id_user_id_unique" on "lesson_views" ("lesson_id", "user_id");
CREATE UNIQUE INDEX "student_progress_student_id_class_id_unique" on "student_progress" ("student_id", "class_id");
CREATE UNIQUE INDEX "ai_providers_name_unique" on "ai_providers" ("name");
CREATE UNIQUE INDEX "ai_usage_provider_date_unique" on "ai_usage" ("provider", "date");
CREATE UNIQUE INDEX "video_meetings_room_id_unique" on "video_meetings" ("room_id");
CREATE INDEX "audit_logs_target_type_target_id_index" on "audit_logs" ("target_type", "target_id");
CREATE UNIQUE INDEX "device_tokens_user_id_token_unique" on "device_tokens" ("user_id", "token");
CREATE UNIQUE INDEX "study_rooms_join_code_unique" on "study_rooms" ("join_code");
CREATE UNIQUE INDEX "study_room_members_study_room_id_user_id_unique" on "study_room_members" ("study_room_id", "user_id");
CREATE UNIQUE INDEX "assignment_group_members_assignment_group_id_user_id_unique" on "assignment_group_members" ("assignment_group_id", "user_id");
DELETE FROM "sqlite_sequence";
COMMIT;
